/**
 * The control plane's real model registry, for the live tests only.
 *
 * The registry's one home is the server's committed document,
 * `backend/services/stigmer-server/src/domain/workflow/registry/data/model-registry.json`
 * (generated by `make sync-model-registry`, bundled into the server by
 * `bundled.ts`, served to the runner at runtime). A live test reads it there
 * by its repository path rather than keeping a copy: a copied id or price is
 * a second home that drifts, and the live tier exists to catch exactly the id
 * a real provider no longer knows. This is the one runner test helper that
 * reads another package's file; live tests never ship, so the coupling is to
 * the repository layout only, and `__tests__/real-model-registry.test.ts`
 * fails in the ordinary suite the day the file moves.
 *
 * The hermetic fixture (`model-registry-fixture.ts`) stays what every other
 * test reads: round prices and ids no provider is ever sent.
 */
import { readFileSync } from "node:fs";

/** One registry row, as far as the live tests read it. */
export interface RealRegistryRow {
  readonly id: string;
  /** The id the provider is sent; absent when it is the registry id itself. */
  readonly apiModelId?: string;
  readonly provider: string;
  readonly harness: string;
}

export interface RealRegistryDocument {
  readonly models: readonly RealRegistryRow[];
}

/** The server's committed registry, relative to this file: `src/__test-utils__` up to `backend/services`. */
export const REAL_REGISTRY_PATH = new URL(
  "../../../stigmer-server/src/domain/workflow/registry/data/model-registry.json",
  import.meta.url,
);

/** The registry id of the Cursor harness's Auto pool: a routing choice, not a model the catalog lists. */
const CURSOR_AUTO_POOL = "default";

function isRow(value: unknown): value is RealRegistryRow {
  if (typeof value !== "object" || value === null) return false;
  const row = value as Record<string, unknown>;
  return (
    typeof row.id === "string" &&
    typeof row.provider === "string" &&
    typeof row.harness === "string" &&
    (row.apiModelId === undefined || typeof row.apiModelId === "string")
  );
}

/** Read and shape-check the committed registry. Throws, naming the file, when it is not the expected shape. */
export function realModelRegistry(): RealRegistryDocument {
  const parsed: unknown = JSON.parse(readFileSync(REAL_REGISTRY_PATH, "utf-8"));
  const models = (parsed as { models?: unknown }).models;
  if (!Array.isArray(models) || !models.every(isRow)) {
    throw new Error(`${REAL_REGISTRY_PATH.pathname} is not a model registry document ({ models: [{ id, provider, harness }] })`);
  }
  return { models };
}

/** The id the runner sends the provider for a native row (`resolveToApiModelId`'s rule). */
export function providerModelId(row: RealRegistryRow): string {
  return row.apiModelId ?? row.id;
}

/** The native harness's rows: every model a native turn may be sent to Anthropic as. */
export function nativeRows(document: RealRegistryDocument): readonly RealRegistryRow[] {
  return document.models.filter((m) => m.harness === "native");
}

/** The Cursor harness's catalog rows, without the Auto pool. */
export function cursorCatalogRows(document: RealRegistryDocument): readonly RealRegistryRow[] {
  return document.models.filter((m) => m.harness === "cursor" && m.id !== CURSOR_AUTO_POOL);
}
